import{_ as e,o as s,c as o,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Direcciones futuras del combate","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/future-directions.md","filePath":"es/game-design/combat/future-directions.md"}'),n={name:"es/game-design/combat/future-directions.md"};function t(r,a,d,c,l,p){return s(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="future-combat-directions" tabindex="-1">Direcciones futuras del combate <a class="header-anchor" href="#future-combat-directions" aria-label="Enlace permanente a &quot;Direcciones futuras del combate&quot;">​</a></h1><p><strong>Estado: Propuesto / Sin resolver. Implementación: ausente; fuera de Slice 0.</strong></p><p>Las técnicas candidatas incluyen ataques precisos/pesados, fintas, respuestas defensivas, desarme, barrido y ataques rápidos. La stamina es un posible recurso de compromiso; esto no adopta automáticamente las habilidades de maná de AOS. Tactics puede revelar oportunidades que modifiquen ocasiones programadas en lugar de conceder golpes gratuitos. Los golpes retenidos y las posturas siguen siendo exploratorios.</p><p>Cleave/propagación puede aplicar efectos locales secundarios acotados a regiones relacionadas. Grandes hachas, martillos de guerra, espadas a dos manos y lanzas pueden tener funciones diferentes; la ranura <code>TwoHanded</code> por sí sola no debe habilitar el mismo efecto. Todavía no se acepta ningún grafo de adyacencia, probabilidades, orden de mitigación ni límite de regiones. Las actualizaciones locales secundarias no deben duplicar comprobaciones completas de impacto, daño global, efectos activados ni desgaste del equipo.</p><p>La persistencia, curación, perfiles de criaturas, evaluación ilustrada nativa, fórmulas definitivas de habilidades y canalizaciones alternativas de animación siguen siendo propuestas separadas. La primitiva corporal podría aceptar más adelante varias actualizaciones acotadas, pero ese punto de extensión no implementa cleave.</p><p><strong>Carencia:</strong> obtener primero observaciones de Slice 0; no convertir esta lista de candidatos en un calendario aprobado de entregas.</p><h2 id="proposed-localized-magic" tabindex="-1">Magia localizada con estado Propuesto <a class="header-anchor" href="#proposed-localized-magic" aria-label="Enlace permanente a &quot;Magia localizada con estado Propuesto&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/magic.html#localized-magic-and-injury">Rediseño de magia v0.1</a> añade perfiles futuros de impacto específicos por hechizo, intención anatómica enfocada e interacciones de lesión/concentración. La magia multirregional y las penalizaciones de lanzamiento necesitan sus propios contratos; no heredan automáticamente el ajuste cuerpo a cuerpo ni amplían el alcance autorizado de Slice 0.</p><h2 id="combat-foundation-ownership" tabindex="-1">Responsabilidad de los fundamentos de combate <a class="header-anchor" href="#combat-foundation-ownership" aria-label="Enlace permanente a &quot;Responsabilidad de los fundamentos de combate&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/weapons-and-damage.html">Armas</a>, <a href="/Syrolands-Public/es/game-design/combat/armor-and-mitigation.html">armadura</a> y <a href="/Syrolands-Public/es/game-design/combat/stamina-and-reactive-combat.html">stamina/entrada</a> amplían propuestas relacionadas. El conflicto de entrada manual y las <a href="/Syrolands-Public/es/game-design/combat/status-and-open-questions.html">decisiones abiertas</a> siguen sin resolverse; este batch no aprueba ni implementa las mecánicas avanzadas anteriores.</p>',10)])])}const g=e(n,[["render",t]]);export{u as __pageData,g as default};
